{
  "name": "todomvc-shakedown",
  "version": "0.1.0",
  "private": true,
  "scripts": { "test": "cucumber-js" },
  "devDependencies": { "@cucumber/cucumber": "*", "happy-dom": "*" }
}

arguments.content:
{
  "watch1": {
    "scenarios": [
      "features/todos.feature:Adding a todo by pressing Enter",
      "features/todos.feature:Whitespace-only input is rejected",
      "features/todos.feature:Input is trimmed before creating",
      "features/todos.feature:Main and footer hidden when no todos exist",
      "features/todos.feature:Multiple todos can be added"
    ]
  },
  "watch2": {
    "scenarios": [
      "features/toggle.feature:Clicking the checkbox marks a todo as completed",
      "features/toggle.feature:Clicking the checkbox again marks a todo as active",
      "features/toggle.feature:Toggle-all marks all todos as completed",
      "features/toggle.feature:Toggle-all reflects individual completion state",
      "features/toggle.feature:Toggle-all unchecking marks all todos as active"
    ]
  },
  "watch3": {
    "scenarios": [
      "features/editing.feature:Double-clicking a todo enters edit mode",
      "features/editing.feature:Pressing Enter saves the edit",
      "features/editing.feature:Pressing Escape discards the edit",
      "features/editing.feature:Blurring the input saves the edit",
      "features/editing.feature:Editing to empty destroys the todo",
      "features/editing.feature:Edit input is trimmed"
    ]
  },
  "watch4": {
    "scenarios": [
      "features/delete.feature:Clicking the destroy button removes a todo",
      "features/delete.feature:Destroying one todo leaves others intact"
    ]
  },
  "watch5": {
    "scenarios": [
      "features/clear-completed.feature:Clear completed removes all completed todos",
      "features/clear-completed.feature:Clear completed button is hidden when no completed todos exist",
      "features/clear-completed.feature:Clear completed button is visible when completed todos exist",
      "features/clear-completed.feature:Toggle-all is unchecked after clearing completed"
    ]
  },
  "watch6": {
    "scenarios": [
      "features/counter.feature:Counter shows zero items when no todos exist",
      "features/counter.feature:Counter shows one item for a single active todo",
      "features/counter.feature:Counter shows correct count with mixed states",
      "features/counter.feature:Counter updates when a todo is toggled",
      "features/counter.feature:Counter uses plural form for multiple items"
    ]
  },
  "watch7": {
    "scenarios": [
      "features/filtering.feature:All filter shows all todos",
      "features/filtering.feature:Active filter shows only active todos",
      "features/filtering.feature:Completed filter shows only completed todos",
      "features/filtering.feature:Active filter is default on load",
      "features/filtering.feature:Toggling a todo in filtered view removes it from the current filter"
    ]
  },
  "watch8": {
    "scenarios": [
      "features/persistence.feature:Todos are saved to localStorage after creation",
      "features/persistence.feature:Completed state is persisted",
      "features/persistence.feature:Todos survive page reload",
      "features/persistence.feature:Deleted todos do not reappear after reload"
    ]
  }
}

